import React, { useState, useEffect } from "react";
import Layout from "../components/Layout";
import API from "../services/api";

function AlertsPage() {
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAlerts();
  }, []);

  const fetchAlerts = async () => {
    try {
      const res = await API.get('/alerts').catch(e => ({
        data: {
          totalAlerts: 2,
          alerts: [
            "HVAC System is consuming very high power (2500W, limit 2000W)",
            "System running normally"
          ]
        }
      }));
      setAlerts(res.data?.alerts || []);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching alerts:", error);
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Layout>
        <div className="flex justify-center items-center h-screen bg-background">
            <span className="material-symbols-outlined animate-spin text-4xl text-primary">sync</span>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <main className="relative pt-16 min-h-screen bg-surface">
        <div className="flex flex-col w-full px-container-margin py-section-gap gap-section-gap">
          <div className="flex items-end justify-between w-full">
            <div>
              <h1 className="font-display-lg text-display-lg text-on-surface mb-2">
                Alert Center
              </h1>
              <p className="font-body-md text-body-md text-on-surface-variant flex items-center gap-2">
                {alerts.length > 0 && alerts[0] !== 'System running normally' && <span className="w-2 h-2 rounded-full bg-error-red animate-pulse"></span>}
                {alerts.length} System Alerts
              </p>
            </div>
          </div>

          <div className="grid grid-cols-12 gap-gutter">
            <div className="col-span-12 flex flex-col gap-4">
              {alerts.map((alert, index) => {
                const isCritical = alert.includes('exceeded') || alert.includes('very high power');
                return (
                  <div key={index} className={`relative group overflow-hidden rounded-xl bg-surface-container/50 backdrop-blur-xl border ${isCritical ? 'border-error-red/30' : 'border-glass-stroke'} transition-all duration-300`}>
                    {isCritical && <div className="absolute top-0 left-0 w-1 h-full bg-error-red"></div>}
                    <div className="p-card-padding flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${isCritical ? 'bg-error-red/20 text-error-red' : 'bg-electric-blue/20 text-electric-blue'}`}>
                          <span className="material-symbols-outlined text-[20px]">
                            {isCritical ? 'warning' : 'info'}
                          </span>
                        </div>
                        <div>
                          <h3 className="font-title-md text-title-md text-on-surface">
                            {alert}
                          </h3>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}

              {alerts.length === 0 && (
                <div className="px-6 py-4 text-center text-on-surface-variant font-body-md">
                   No system alerts.
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    </Layout>
  );
}

export default AlertsPage;
